@isTest private class CurrentBaseApplauncherDeterministic001Test {
    @isTest static void applauncherDeterministic001Witness() {
        applauncher.AccountSettingsController accountSettings = new applauncher.AccountSettingsController();
        System.assertNotEquals(null, accountSettings);
        System.assertNotEquals(null, accountSettings.clone());

        applauncher.AppLauncherHelper appLauncherHelper = new applauncher.AppLauncherHelper();
        System.assertNotEquals(null, appLauncherHelper);
        System.assertNotEquals(null, appLauncherHelper.clone());

        applauncher.AppLauncherSetupReordererController reorderer = new applauncher.AppLauncherSetupReordererController();
        System.assertNotEquals(null, reorderer);
        System.assertNotEquals(null, reorderer.clone());

        applauncher.AppMenu appMenu = new applauncher.AppMenu();
        System.assertNotEquals(null, appMenu);
        System.assertNotEquals(null, appMenu.clone());
        applauncher.AppMenu.setAppVisibility('001000000000001', true);
        applauncher.AppMenu.setOrgSortOrder(new List<Id>{'001000000000001', '001000000000002'});
        applauncher.AppMenu.setUserSortOrder(new List<Id>{'001000000000001', '001000000000002'});

        applauncher.ChangePasswordController changePassword = new applauncher.ChangePasswordController();
        System.assertNotEquals(null, changePassword);
        System.assertNotEquals(null, changePassword.clone());

        applauncher.CommerceStoreController commerceStore = new applauncher.CommerceStoreController();
        System.assertNotEquals(null, commerceStore);
        System.assertNotEquals(null, commerceStore.clone());
        Map<String,Object> commerceContext = applauncher.CommerceStoreController.getCommerceContext();
        System.assertEquals(0, commerceContext.size());

        applauncher.CommunityLogoController communityLogo = new applauncher.CommunityLogoController();
        System.assertNotEquals(null, communityLogo);
        System.assertNotEquals(null, communityLogo.clone());
        System.assertEquals(null, applauncher.CommunityLogoController.getCommunityName());
        System.assertEquals(null, applauncher.CommunityLogoController.getLogoURL());

        applauncher.EmployeeLoginLinkController employeeLoginLink = new applauncher.EmployeeLoginLinkController();
        System.assertNotEquals(null, employeeLoginLink);
        System.assertNotEquals(null, employeeLoginLink.clone());
        System.assertEquals(null, applauncher.EmployeeLoginLinkController.getEmployeeLoginUrl('/home'));
        System.assertEquals(null, applauncher.EmployeeLoginLinkController.getIsAllowInternalUserLoginEnabled());

        applauncher.ForgotPasswordController forgotPassword = new applauncher.ForgotPasswordController();
        System.assertNotEquals(null, forgotPassword);
        System.assertNotEquals(null, forgotPassword.clone());

        applauncher.IdentityHeaderController identityHeader = new applauncher.IdentityHeaderController();
        System.assertNotEquals(null, identityHeader);
        System.assertNotEquals(null, identityHeader.clone());

        applauncher.LoginFormController loginForm = new applauncher.LoginFormController();
        System.assertNotEquals(null, loginForm);
        System.assertNotEquals(null, loginForm.clone());

        applauncher.SelfRegisterController selfRegister = new applauncher.SelfRegisterController();
        System.assertNotEquals(null, selfRegister);
        System.assertNotEquals(null, selfRegister.clone());

        applauncher.SocialLoginController socialLogin = new applauncher.SocialLoginController();
        System.assertNotEquals(null, socialLogin);
        System.assertNotEquals(null, socialLogin.clone());
    }
}
